grid=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]; edge=False
   while q:
    x,y=q.popleft();comp.append((x,y));edge |= x in (0,R-1) or y in (0,C-1)
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]]==0 and z not in seen: seen.add(z);q.append(z)
   comps.append((len(comp),edge,comp))
comps
